from collections import OrderedDict

class LRUCache:

    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        value = self.cache.pop(key)
        self.cache[key] = value  # Move the accessed item to the end of the cache (most recently used)
        return value

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.pop(key)  # Remove the existing entry to move it to the end of the cache (eviction)
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)  # Remove the least recently used item from the cache (eviction)
        self.cache[key] = value  # Add the new item to the cache (most recently used)

